  const loadReqEditRows = async (approvedOnly = false) => {
    try {
      setReqEditLoading(true);

      const endpoint = approvedOnly
        ? `/request-edit-transactions/approved?requestedUpto=${encodeURIComponent(reqEditRequestDate)}`
        : `/request-edit-transactions?requestedUpto=${encodeURIComponent(reqEditRequestDate)}`;

      const data = await apiRequest(endpoint);
      const records = Array.isArray(data) ? data : [];

      setReqEditRows(
        records.map((record) => ({
          id: record.id,
          requestedUpto: String(record.requestedUpto || ""),
          groupName: String(record.groupName || ""),
          option: String(record.option || ""),
          approved: Boolean(record.approved),
        }))
      );
      setSelectedReqEditId(null);
    } catch (error) {
      console.error("Could not load Request for Editing transactions:", error);
      alert(`Unable to load Request for Editing transactions from PostgreSQL.\n${error.message}`);
    } finally {
      setReqEditLoading(false);
    }
  };

  const listReqEditGroups = async () => {
    try {
      setReqEditLoading(true);

      const [requestData, mapDigData] = await Promise.all([
        reqEditRequestDate
          ? apiRequest(`/request-edit-transactions?requestedUpto=${encodeURIComponent(reqEditRequestDate)}`)
          : Promise.resolve([]),
        apiRequest("/map-dig"),
      ]);

      const requests = Array.isArray(requestData) ? requestData : [];
      const mapRecords = Array.isArray(mapDigData) ? mapDigData : [];
      const requestByGroup = new Map(
        requests.map((record) => [String(record.groupName || "").trim(), record])
      );

      const groupNames = [];
      const seenGroups = new Set();

      mapRecords.forEach((record) => {
        const groupName = String(record.groupName || "").trim();
        if (groupName && !seenGroups.has(groupName)) {
          seenGroups.add(groupName);
          groupNames.push(groupName);
        }
      });

      requests.forEach((record) => {
        const groupName = String(record.groupName || "").trim();
        if (groupName && !seenGroups.has(groupName)) {
          seenGroups.add(groupName);
          groupNames.push(groupName);
        }
      });

      if (!groupNames.length) {
        alert("No groups found. Please add groups in Map DIG first.");
        setReqEditRows([]);
        return;
      }

      setReqEditRows(
        groupNames.map((groupName) => {
          const record = requestByGroup.get(groupName);
          return {
            id: record?.id || null,
            requestedUpto: reqEditRequestDate,
            groupName,
            option: String(record?.option || ""),
            approved: Boolean(record?.approved),
          };
        })
      );
      setSelectedReqEditId(null);
    } catch (error) {
      console.error("Could not list Request for Editing groups:", error);
      alert(`Unable to load groups for Request for Editing.\n${error.message}`);
    } finally {
      setReqEditLoading(false);
    }
  };

  const saveReqEditRows = async () => {
    if (!reqEditRequestDate) {
      alert("Please select Requested Upto.");
      return;
    }

    if (!reqEditRows.length) {
      alert("No group details available to save.");
      return;
    }

    try {
      setReqEditLoading(true);
      const savedRows = [];

      for (const row of reqEditRows) {
        const groupName = String(row.groupName || "").trim();
        if (!groupName) continue;

        const payload = {
          requestedUpto: reqEditRequestDate,
          groupName,
          option: String(row.option || "").trim(),
          approved: Boolean(row.approved),
        };

        const saved = row.id
          ? await apiRequest(`/request-edit-transactions/${row.id}`, {
              method: "PUT",
              body: JSON.stringify(payload),
            })
          : await apiRequest("/request-edit-transactions", {
              method: "POST",
              body: JSON.stringify(payload),
            });

        savedRows.push({
          id: saved.id,
          requestedUpto: String(saved.requestedUpto || reqEditRequestDate),
          groupName: String(saved.groupName || groupName),
          option: String(saved.option || payload.option),
          approved: Boolean(saved.approved),
        });
      }

      setReqEditRows(savedRows);
      setSelectedReqEditId(null);
      alert("Request for Editing transactions saved successfully to PostgreSQL!");
    } catch (error) {
      console.error("Request for Editing save error:", error);
      alert(`Unable to save Request for Editing details.\n${error.message}`);
    } finally {
      setReqEditLoading(false);
    }
  };

