  const [page, setPageState] = useState(() => {
    // Restore the last page stored in browser history when possible.
    return window.history.state?.saveAppPage || "login";
  });

  // =========================================================
  // IN-APP BROWSER HISTORY
  // Keeps the browser Back/Forward buttons inside the React app.
  // Every menu click creates a history entry, so Back returns to
  // the previous page instead of leaving localhost:5173.
  // =========================================================
  const setPage = (nextPage) => {
    if (page === nextPage) return;

    // Create one browser-history entry for each in-app page change.
    // The URL stays the same, so the app does not reload.
    window.history.pushState(
      { ...(window.history.state || {}), saveAppPage: nextPage },
      "",
      window.location.href
    );

    setPageState(nextPage);
  };

  useEffect(() => {
    // Mark the current browser entry as an app page.
    window.history.replaceState(
      { ...(window.history.state || {}), saveAppPage: page },
      "",
      window.location.href
    );

    const handleBrowserBackForward = (event) => {
      const historyPage = event.state?.saveAppPage;

      if (historyPage) {
        setPageState(historyPage);
      }
    };

    window.addEventListener("popstate", handleBrowserBackForward);

    return () => {
      window.removeEventListener("popstate", handleBrowserBackForward);
    };
  }, []);

