  const loadRocLimitsFromDatabase = async (dateFilter = "") => {
    try {
      setRocLimitLoading(true);

      const data = await apiRequest("/roc-limits");
      const records = Array.isArray(data) ? data : [];

      const filteredRecords = dateFilter
        ? records.filter(
            (record) =>
              String(record?.rocLimitDate || "").trim() ===
              String(dateFilter).trim()
          )
        : records;

      setRocLimitRows(filteredRecords);

      if (filteredRecords.length > 0 && !dateFilter) {
        setRocLimitDate(filteredRecords[0].rocLimitDate || "");
      }

      return filteredRecords;
    } catch (error) {
      console.error("Could not load ROC Limit data:", error);
      alert(`Unable to load ROC Limit data from database.\n${error.message}`);
      return [];
    } finally {
      setRocLimitLoading(false);
    }
  };

