  // =========================================================
  // OTHERS -> DIG MEETING
  // PostgreSQL-backed DIG Group Meeting Conducting Status.
  // =========================================================
  const [digMeetingRows, setDigMeetingRows] = useState([]);
  const [digMeetingMonth, setDigMeetingMonth] = useState("");
  const [digMeetingLoading, setDigMeetingLoading] = useState(false);

  const getDigMeetingMonths = () => {
    const months = [];
    const now = new Date();

    for (let index = 0; index < 24; index += 1) {
      const date = new Date(now.getFullYear(), now.getMonth() - index, 1);
      const value = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
      const label = date.toLocaleString("en-US", { month: "long", year: "numeric" });
      months.push({ value, label });
    }

    return months;
  };

  const updateDigMeetingRow = (index, status) => {
    setDigMeetingRows((previous) =>
      previous.map((row, rowIndex) =>
        rowIndex === index ? { ...row, status } : row
      )
    );
  };

  const loadDigMeetingFromDatabase = async () => {
    if (!digMeetingMonth) {
      alert("Kindly select date");
      return;
    }

    try {
      setDigMeetingLoading(true);

      const [meetingData, mapDigData] = await Promise.all([
        apiRequest(`/dig-meeting?month=${encodeURIComponent(digMeetingMonth)}`),
        apiRequest("/map-dig"),
      ]);

      const meetings = Array.isArray(meetingData) ? meetingData : [];
      const mapDigRecords = Array.isArray(mapDigData) ? mapDigData : [];

      const groupNames = [];
      const seenGroups = new Set();

      mapDigRecords.forEach((record) => {
        const groupName = String(record?.groupName || "").trim();
        if (groupName && !seenGroups.has(groupName)) {
          seenGroups.add(groupName);
          groupNames.push(groupName);
        }
      });

      meetings.forEach((record) => {
        const groupName = String(record?.digGroupName || "").trim();
        if (groupName && !seenGroups.has(groupName)) {
          seenGroups.add(groupName);
          groupNames.push(groupName);
        }
      });

      const meetingByGroup = new Map(
        meetings.map((record) => [String(record.digGroupName || "").trim(), record])
      );

      setDigMeetingRows(
        groupNames.map((groupName) => {
          const record = meetingByGroup.get(groupName);
          return {
            id: record?.id,
            digGroupName: groupName,
            status: record?.status || "",
          };
        })
      );
    } catch (error) {
      console.error("Could not load DIG Meeting data:", error);
      alert(`Unable to load DIG Meeting data from database.\n${error.message}`);
    } finally {
      setDigMeetingLoading(false);
    }
  };

  const saveDigMeeting = async () => {
    if (!digMeetingMonth) {
      alert("Kindly select date");
      return;
    }

    if (!digMeetingRows.length) {
      alert("No DIG groups available. Please add groups in Map DIG first.");
      return;
    }

    const incomplete = digMeetingRows.some((row) => !row.status);
    if (incomplete) {
      alert("Please select a meeting status for every DIG group.");
      return;
    }

    try {
      setDigMeetingLoading(true);
      const savedRows = [];

      for (const row of digMeetingRows) {
        const payload = {
          meetingMonth: digMeetingMonth,
          digGroupName: row.digGroupName,
          status: row.status,
        };

        const saved = row.id
          ? await apiRequest(`/dig-meeting/${row.id}`, {
              method: "PUT",
              body: JSON.stringify(payload),
            })
          : await apiRequest("/dig-meeting", {
              method: "POST",
              body: JSON.stringify(payload),
            });

        savedRows.push({
          id: saved.id,
          digGroupName: saved.digGroupName || row.digGroupName,
          status: saved.status || row.status,
        });
      }

      setDigMeetingRows(savedRows);
      alert("DIG Meeting status saved successfully to PostgreSQL!");
    } catch (error) {
      console.error("DIG Meeting save error:", error);
      alert(`Unable to save DIG Meeting status.\n${error.message}`);
    } finally {
      setDigMeetingLoading(false);
    }
  };

  // =========================================================
  // OTHERS -> UNLOCK MEMBERS
  // Uses the existing Member table. Locked members are displayed
  // and selected members can be unlocked by setting locked=false.
  // =========================================================
  const [unlockMemberRows, setUnlockMemberRows] = useState([]);
  const [unlockMemberLoading, setUnlockMemberLoading] = useState(false);

  const loadUnlockMembersFromDatabase = async () => {
    try {
      setUnlockMemberLoading(true);

      const data = await apiRequest("/members");
      const records = Array.isArray(data) ? data : [];

      setUnlockMemberRows(
        records.map((record) => ({
          id: record.id,
          memberCode: String(record.memberCode || ""),
          memberName: String(record.memberName || ""),
          locked: Boolean(
            record.locked ?? record.isLocked ?? record.memberLocked
          ),
          unlock: false,
        }))
      );
    } catch (error) {
      console.error("Could not load Unlock Members data:", error);
      alert(
        `Unable to load Unlock Members data from database.\n${error.message}`
      );
    } finally {
      setUnlockMemberLoading(false);
    }
  };

  const updateUnlockMemberRow = (index, value) => {
    setUnlockMemberRows((previous) =>
      previous.map((row, rowIndex) =>
        rowIndex === index ? { ...row, unlock: value } : row
      )
    );
  };

  const saveUnlockMembers = async () => {
    const selectedRows = unlockMemberRows.filter((row) => row.unlock);

    if (!selectedRows.length) {
      alert("Select atleast one member before clicking save button");
      return;
    }

    try {
      setUnlockMemberLoading(true);

      const savedRows = [];

      for (const row of selectedRows) {
        if (!row.id) {
          continue;
        }

        const databaseMember = memberRecords.find(
          (record) => Number(record?.id) === Number(row.id)
        );

        if (!databaseMember) {
          continue;
        }

        const updatedMember = {
          ...databaseMember,
          locked: false,
        };

        const savedMember = await apiRequest(`/members/${row.id}`, {
          method: "PUT",
          body: JSON.stringify(updatedMember),
        });

        savedRows.push(savedMember);
      }

      if (!savedRows.length) {
        alert("No matching members were found in the database.");
        return;
      }

      setMemberRecords((previous) =>
        previous.map((record) => {
          const updated = savedRows.find(
            (saved) => Number(saved.id) === Number(record.id)
          );
          return updated || record;
        })
      );

      setUnlockMemberRows((previous) =>
        previous.map((row) => {
          const wasUnlocked = savedRows.some(
            (saved) => Number(saved.id) === Number(row.id)
          );

          return wasUnlocked
            ? { ...row, locked: false, unlock: false }
            : row;
        })
      );

      alert("Selected members unlocked successfully in PostgreSQL!");
    } catch (error) {
      console.error("Unlock Members save error:", error);
      alert(
        `Unable to unlock selected members.\n${error.message}`
      );
    } finally {
      setUnlockMemberLoading(false);
    }
  };

  // =========================================================
  // OTHERS -> DIG IMPACT
  // PostgreSQL-backed DIG Group Impact Status.
  // Groups and purpose are taken from Map DIG records.
  // =========================================================
  const [digImpactRows, setDigImpactRows] = useState([]);
  const [digImpactLoading, setDigImpactLoading] = useState(false);

  const loadDigImpactFromDatabase = async () => {
    try {
      setDigImpactLoading(true);

      const [mapData, impactData] = await Promise.all([
        apiRequest("/map-dig"),
        apiRequest("/dig-impact"),
      ]);

      const mapRecords = Array.isArray(mapData) ? mapData : [];
      const impactRecords = Array.isArray(impactData) ? impactData : [];

      const rows = mapRecords.map((record) => {
        const saved = impactRecords.find(
          (impact) =>
            String(impact?.mapDigId ?? "") === String(record?.id ?? "")
        );

        return {
          id: saved?.id ?? null,
          mapDigId: record?.id ?? null,
          groupName: String(record?.groupName || ""),
          purpose: String(record?.primaryReason || ""),
          impactStatus: String(saved?.impactStatus || ""),
        };
      });

      setDigImpactRows(rows);
    } catch (error) {
      console.error("Could not load DIG Impact data:", error);
      alert(`Unable to load DIG Impact data from database.\n${error.message}`);
    } finally {
      setDigImpactLoading(false);
    }
  };

  const updateDigImpactStatus = (index, status) => {
    setDigImpactRows((previous) =>
      previous.map((row, rowIndex) =>
        rowIndex === index ? { ...row, impactStatus: status } : row
      )
    );
  };

  const saveDigImpact = async () => {
    const selectedRows = digImpactRows.filter((row) => row.impactStatus);

    if (!selectedRows.length) {
      alert("Please select any one Report");
      return;
    }

    try {
      setDigImpactLoading(true);
      const savedRows = [];

      for (const row of selectedRows) {
        const payload = {
          mapDigId: row.mapDigId,
          groupName: row.groupName,
          purpose: row.purpose,
          impactStatus: row.impactStatus,
        };

        const saved = row.id
          ? await apiRequest(`/dig-impact/${row.id}`, {
              method: "PUT",
              body: JSON.stringify(payload),
            })
          : await apiRequest("/dig-impact", {
              method: "POST",
              body: JSON.stringify(payload),
            });

        savedRows.push(saved);
      }

      setDigImpactRows((previous) =>
        previous.map((row) => {
          const saved = savedRows.find(
            (item) =>
              String(item?.mapDigId ?? "") === String(row?.mapDigId ?? "")
          );

          return saved
            ? {
                ...row,
                id: saved.id,
                impactStatus: saved.impactStatus || row.impactStatus,
              }
            : row;
        })
      );

      alert("DIG Impact details saved successfully to PostgreSQL!");
    } catch (error) {
      console.error("DIG Impact save error:", error);
      alert(`Unable to save DIG Impact details.\n${error.message}`);
    } finally {
      setDigImpactLoading(false);
    }
  };

