  const transactionListOptions = [
    "LI01 - Receipt List",
    "LI02 - Payment List",
    "LI03 - Journal List",
    "LI04 - Manual Journal List",
    "LI05 - Auto Journal List - Yearly Jrnl",
    "LI05A - Auto Journal List - Monthly Jrnl",
    "LI06 - Bank Loan List",
    "LI07 - Fixed Deposit List",
    "LI08 - Receipt Edit List - Before Locking",
    "LI09 - Payment Edit List - Before Locking",
    "LI10 - Journal Edit List - Before Locking",
  ];

  const [selectedTransactionList, setSelectedTransactionList] = useState(
    transactionListOptions[0]
  );
  const [transactionListFromDate, setTransactionListFromDate] = useState(CURRENT_FINANCIAL_YEAR.startDate);
  const [transactionListToDate, setTransactionListToDate] = useState(CURRENT_FINANCIAL_YEAR.endDate);
  const [transactionListResults, setTransactionListResults] = useState([]);
  const [transactionListLoading, setTransactionListLoading] = useState(false);
  const [transactionListExecuted, setTransactionListExecuted] = useState(false);

  const parseTransactionListDate = (value) => {
    const text = String(value || "").trim();
    if (!text) return null;

    if (/^\d{2}-\d{2}-\d{4}$/.test(text)) {
      const [day, month, year] = text.split("-").map(Number);
      return new Date(year, month - 1, day);
    }

    if (/^\d{4}-\d{2}-\d{2}$/.test(text)) {
      const [year, month, day] = text.split("-").map(Number);
      return new Date(year, month - 1, day);
    }

    const parsed = new Date(text);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  };

  const getTransactionRecordDate = (record, listName) => {
    if (listName.includes("Receipt")) return record.receiptDate;
    if (listName.includes("Payment")) return record.voucherDate;
    if (listName.includes("Journal")) return record.journalDate || record.date;
    if (listName.includes("Fixed Deposit")) return record.fdDate;
    return record.date || record.voucherDate || record.receiptDate || record.fdDate;
  };

  const isDateWithinTransactionListRange = (record, listName) => {
    const recordDate = parseTransactionListDate(getTransactionRecordDate(record, listName));
    if (!recordDate) return true;

    const fromDate = parseTransactionListDate(transactionListFromDate);
    const toDate = parseTransactionListDate(transactionListToDate);

    if (fromDate) fromDate.setHours(0, 0, 0, 0);
    if (toDate) toDate.setHours(23, 59, 59, 999);

    if (fromDate && recordDate < fromDate) return false;
    if (toDate && recordDate > toDate) return false;
    return true;
  };

  const executeTransactionList = async () => {
    try {
      setTransactionListLoading(true);
      setTransactionListExecuted(false);

      let records = [];

      switch (selectedTransactionList) {
        case "LI01 - Receipt List":
        case "LI08 - Receipt Edit List - Before Locking":
          records = [
            ...memberReceiptRecords.map((record) => ({
              ...record,
              _type: "Member Receipt",
              _number: record.receiptNo,
              _date: record.receiptDate,
              _amount: record.total,
              _name: record.memberName || record.memberCode,
            })),
            ...otherReceiptRecords.map((record) => ({
              ...record,
              _type: "Other Receipt",
              _number: record.receiptNo,
              _date: record.receiptDate,
              _amount: record.total,
              _name: record.subLedger,
            })),
          ];
          break;

        case "LI02 - Payment List":
        case "LI09 - Payment Edit List - Before Locking":
          records = [
            ...memberPaymentRecords.map((record) => ({
              ...record,
              _type: "Member Payment",
              _number: record.voucherNo,
              _date: record.voucherDate,
              _amount: record.total,
              _name: record.memberName || record.memberCode,
            })),
            ...otherPaymentRecords.map((record) => ({
              ...record,
              _type: "Other Payment",
              _number: record.voucherNo,
              _date: record.voucherDate,
              _amount: record.total,
              _name: record.sl || record.subLed1,
            })),
          ];
          break;

        case "LI03 - Journal List":
        case "LI04 - Manual Journal List":
        case "LI10 - Journal Edit List - Before Locking":
          records = [
            ...memberJournalRecords.map((record) => ({
              ...record,
              _type: "Member Journal",
              _number: record.jrNo,
              _date: record.date,
              _amount: record.debitTotal || record.creditTotal,
              _name: record.member,
            })),
            ...otherJournalRecords.map((record) => ({
              ...record,
              _type: "Other Journal",
              _number: record.journalNumber,
              _date: record.journalDate,
              _amount: record.debitTotal || record.creditTotal,
              _name: record.generalLedger,
            })),
          ];
          break;

        case "LI07 - Fixed Deposit List":
          records = fixedDepositRecords.map((record) => ({
            ...record,
            _type: "Fixed Deposit",
            _number: record.fdNumber || record.receiptNumber,
            _date: record.fdDate,
            _amount: record.fdAmount,
            _name: `${record.bank || ""}${record.branch ? ` - ${record.branch}` : ""}`,
          }));
          break;

        case "LI05 - Auto Journal List - Yearly Jrnl":
        case "LI05A - Auto Journal List - Monthly Jrnl":
        case "LI06 - Bank Loan List":
          records = [];
          break;

        default:
          records = [];
      }

      const filtered = records
        .filter((record) => isDateWithinTransactionListRange(record, selectedTransactionList))
        .sort((a, b) => {
          const da = parseTransactionListDate(a._date)?.getTime() || 0;
          const db = parseTransactionListDate(b._date)?.getTime() || 0;
          return db - da;
        });

      setTransactionListResults(filtered);
      setTransactionListExecuted(true);
    } catch (error) {
      console.error("Transaction List execute error:", error);
      alert(`Unable to load Transaction List.\n${error.message}`);
    } finally {
      setTransactionListLoading(false);
    }
  };

