  const uploadIsMemberSelector = selectedOthersItem === "Voter Id - Mem";

  const buildUploadRows = () => {
    const isMemberBankPassbook = selectedOthersItem === "Member";
    const isSpouseBankPassbook = selectedOthersItem === "Spouse";

    const members = isMemberBankPassbook || isSpouseBankPassbook
      ? memberRecords.map((record) => {
          const matchingAccounts = bankAccountRecords.filter((account) => {
            const accountMemberId =
              account.memberId == null ? "" : String(account.memberId);
            const recordId =
              record.id == null ? "" : String(record.id);

            const accountMemberCode =
              String(account.memberCode || "").trim();
            const recordMemberCode =
              String(record.memberCode || "").trim();

            const accountMemberName =
              String(account.memberName || "").trim().toLowerCase();
            const recordMemberName =
              String(record.memberName || "").trim().toLowerCase();

            return (
              (recordId && accountMemberId && recordId === accountMemberId) ||
              (recordMemberCode &&
                accountMemberCode &&
                recordMemberCode === accountMemberCode) ||
              (recordMemberName &&
                accountMemberName &&
                recordMemberName === accountMemberName)
            );
          });

          /*
           * Bank Account records already contain Family Member No.
           * For Upload Bank Passbook - Spouse, prefer the account that
           * has a Family Member No. For the Member page, prefer the
           * account without a Family Member No.
           */
          const account = isSpouseBankPassbook
            ? matchingAccounts.find(
                (item) => String(item.familyMemberNo || "").trim()
              )
            : matchingAccounts.find(
                (item) => !String(item.familyMemberNo || "").trim()
              ) || matchingAccounts[0];

          return {
            memberCode: record.memberCode || "",
            memberName: record.memberName || "",
            documentNo: account?.accountNumber || "",
          };
        })
      : memberRecords.length
        ? memberRecords.map((record) => ({
            memberCode: record.memberCode || "",
            memberName: record.memberName || "",
            documentNo:
              selectedOthersItem === "Aadhaar - Mem"
                ? record.aadharId || ""
                : selectedOthersItem === "Aadhaar - Spouse"
                  ? record.spouseAadharId || ""
                  : selectedOthersItem === "Voter Id - Mem"
                    ? record.voterId || ""
                    : selectedOthersItem === "Voter Id - Spouse"
                      ? record.spouseVoterId || ""
                      : selectedOthersItem === "Ration Card"
                        ? record.rationCardNo || ""
                        : selectedOthersItem === "PAN Card"
                          ? record.panCardNo || ""
                          : "",
          }))
        : attendanceMembers.map((member) => {
          const [code, ...nameParts] = member.split("-");
          return {
            memberCode: code || "",
            memberName: nameParts.join("-") || member,
            documentNo: "",
          };
        });

    setUploadRows(
      members.map((row) => ({
        ...row,
        fileName: "",
        file: null,
      }))
    );
  };

