  const [attendanceMode, setAttendanceMode] = useState("add");

  // Attendance members come only from Member Master records.
  // No sample/hard-coded member names are used here.
  const attendanceMembers = memberRecords
    .map((record) => {
      const code = String(record.memberCode || "").trim();
      const name = String(record.memberName || "").trim();

      if (code && name) return `${code}-${name}`;
      return code || name;
    })
    .filter(Boolean);

  useEffect(() => {
    apiRequest("/attendances")
      .then(setAttendanceRecords)
      .catch((error) => console.error("Attendance load error:", error));
  }, []);

  const resetAttendanceForm = () => {
    setAttendanceDate("");
    setRvColDate("");
    setAttendanceReason("Leaders Domination");
    setAttendanceOtherReason("");
    setAttendanceNotConducted(false);
    setAttendanceSpecialMeeting(false);
    setAttendedMembers([]);
    setSelectedAttendanceId(null);
    setAttendanceMode("add");
  };

  const handleAttendanceSave = async () => {
    if (!attendanceNotConducted && !attendanceDate) {
      alert("Please select Meeting Date.");
      return;
    }

    try {
      const payload = {
        meetingDate: attendanceDate,
        rvColDate,
        reason: attendanceReason,
        otherReason: attendanceOtherReason,
        notConducted: attendanceNotConducted,
        specialMeeting: attendanceSpecialMeeting,
        attendedMembers: attendedMembers.join(",")
      };

      if (attendanceMode === "edit" && selectedAttendanceId) {
        const updated = await apiRequest(`/attendances/${selectedAttendanceId}`, {
          method: "PUT",
          body: JSON.stringify(payload)
        });
        setAttendanceRecords((previous) =>
          previous.map((record) => record.id === selectedAttendanceId ? updated : record)
        );
        alert("Attendance updated successfully!");
      } else {
        const saved = await apiRequest("/attendances", {
          method: "POST",
          body: JSON.stringify(payload)
        });
        setAttendanceRecords((previous) => [...previous, saved]);
        alert("Attendance saved successfully!");
      }
      resetAttendanceForm();
    } catch (error) {
      console.error("Attendance save error:", error);
      alert("Unable to save attendance.");
    }
  };

  const handleAttendanceEdit = (record) => {
    setAttendanceMode("edit");
    setSelectedAttendanceId(record.id);
    setAttendanceDate(record.meetingDate || "");
    setRvColDate(record.rvColDate || "");
    setAttendanceReason(record.reason || "Leaders Domination");
    setAttendanceOtherReason(record.otherReason || "");
    setAttendanceNotConducted(!!record.notConducted);
    setAttendanceSpecialMeeting(!!record.specialMeeting);
    setAttendedMembers(record.attendedMembers ? record.attendedMembers.split(",").filter(Boolean) : []);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

