  useEffect(() => {
    let cancelled = false;

    const loadOtherJournals = async () => {
      try {
        setOtherJournalLoading(true);
        const data = await apiRequest("/other-journals");

        if (!cancelled) {
          const records = Array.isArray(data)
            ? data.map((record) => ({
                ...record,
                rows:
                  typeof record.rowsJson === "string"
                    ? JSON.parse(record.rowsJson || "[]")
                    : (record.rows || []),
              }))
            : [];

          setOtherJournalRecords(records);
        }
      } catch (error) {
        console.error("Could not load Other Journal data:", error);
      } finally {
        if (!cancelled) setOtherJournalLoading(false);
      }
    };

    loadOtherJournals();

    return () => {
      cancelled = true;
    };
  }, []);

  const saveOtherJournal = async () => {
    if (!String(otherJournalData.journalDate || "").trim()) {
      alert("Please enter Journal Date.");
      return;
    }

    try {
      setOtherJournalLoading(true);

      const payload = {
        ...otherJournalData,
        rowsJson: JSON.stringify(otherJournalData.rows || []),
      };

      delete payload.rows;

      let saved;

      if (selectedOtherJournalId) {
        saved = await apiRequest(`/other-journals/${selectedOtherJournalId}`, {
          method: "PUT",
          body: JSON.stringify(payload),
        });

        const savedRecord = {
          ...saved,
          rows:
            typeof saved.rowsJson === "string"
              ? JSON.parse(saved.rowsJson || "[]")
              : [],
        };

        setOtherJournalRecords((previous) =>
          previous.map((item) =>
            item.id === selectedOtherJournalId ? savedRecord : item
          )
        );

        alert("Other Journal updated successfully!");
      } else {
        saved = await apiRequest("/other-journals", {
          method: "POST",
          body: JSON.stringify(payload),
        });

        const savedRecord = {
          ...saved,
          rows:
            typeof saved.rowsJson === "string"
              ? JSON.parse(saved.rowsJson || "[]")
              : [],
        };

        setOtherJournalRecords((previous) => [...previous, savedRecord]);
        alert("Other Journal saved successfully!");
      }

      const savedRows =
        typeof saved.rowsJson === "string"
          ? JSON.parse(saved.rowsJson || "[]")
          : [];

      setOtherJournalData({
        journalNumber: saved.journalNumber || "1",
        journalDate: saved.journalDate || "",
        generalLedger: saved.generalLedger || "Administrative Expenses - 4410",
        subLedgerMain:
          saved.subLedgerMain ||
          "Bank Charges Not Related to SHG-Bank Linkage - 4411",
        debitCredit: saved.debitCredit || "Debit",
        amountMain: saved.amountMain || "",
        amountMode: saved.amountMode || "No",
        rows: savedRows,
        narration: saved.narration || "",
        creditTotal: saved.creditTotal || "",
        debitTotal: saved.debitTotal || "",
      });

      setSelectedOtherJournalId(saved.id);
      setOtherJournalMode("view");
    } catch (error) {
      console.error("Other Journal save error:", error);
      alert(`Unable to save Other Journal details.\\n${error.message}`);
    } finally {
      setOtherJournalLoading(false);
    }
  };

