    const editGenDetail = async () => {
      const code = String(value("memberCode") || "").trim();

      if (!code) {
        setStatus("Enter Member Code and click Edit.");
        return;
      }

      setDisMemberLoading(true);

      try {
        const rows = await apiRequest("/members");
        const list = Array.isArray(rows) ? rows : [];

        const found = list.find(
          (member) =>
            String(member.memberCode || "").trim().toLowerCase() ===
            code.toLowerCase()
        );

        if (!found) {
          setStatus(`Member Code "${code}" was not found.`);
          return;
        }

        setSelectedDisMemberId(found.id);
        setValues({
          memberCode: found.memberCode ?? "",
          memberName: found.memberName ?? "",
          regionalMemberName: found.regionalMemberName ?? "",
          designation: found.designation ?? "",
          date: found.date ?? "",
          dateOfJoining: found.dateOfJoining ?? "",
          yearOfBirth: found.yearOfBirth ?? "",
          maritalStatus: found.maritalStatus ?? "",
          husbandFatherName: found.husbandFatherName ?? "",
          aliveStatus: found.aliveStatus ?? "",
          category: found.category ?? "",
          familyCategory: found.familyCategory ?? "",
          caste: found.caste ?? "",
          rationCard: found.rationCard ?? "",
          rationCardNo: found.rationCardNo ?? "",
          voterId: found.voterId ?? "",
          aadharId: found.aadharId ?? "",
          mobileNumber: found.mobileNumber ?? "",
          regularSavings: found.regularSavings ?? "",
          specialSavings: found.specialSavings ?? "",
          locked: Boolean(found.locked),
        });
        setStatus(`Member "${found.memberName || code}" loaded for editing.`);
      } catch (error) {
        console.error("DIS Gen. Detail edit error:", error);
        setStatus(`Unable to load member: ${error.message}`);
      } finally {
        setDisMemberLoading(false);
      }
    };

    const saveGenDetail = async () => {
      const memberCode = String(value("memberCode") || "").trim();
      const memberName = String(value("memberName") || "").trim();
      const regionalMemberName = String(
        value("regionalMemberName") || ""
      ).trim();

      if (!memberCode) {
        setStatus("Member Code is required.");
        return;
      }

      if (!memberName) {
        setStatus("Member Name is required.");
        return;
      }

      if (!regionalMemberName) {
        setStatus("Regional Member Name is required.");
        return;
      }

      const payload = {
        memberCode,
        memberName,
        regionalMemberName,
        designation: value("designation"),
        date: value("date"),
        dateOfJoining: value("dateOfJoining"),
        yearOfBirth: value("yearOfBirth"),
        maritalStatus: value("maritalStatus"),
        husbandFatherName: value("husbandFatherName"),
        aliveStatus: value("aliveStatus"),
        category: value("category"),
        familyCategory: value("familyCategory"),
        caste: value("caste"),
        rationCard: value("rationCard"),
        rationCardNo: value("rationCardNo"),
        voterId: value("voterId"),
        aadharId: value("aadharId"),
        mobileNumber: value("mobileNumber"),
        regularSavings: value("regularSavings"),
        specialSavings: value("specialSavings"),
        /*
         * Keep the current lock state so DIS Gen. Detail editing does not
         * accidentally unlock a member used by Others -> Unlock Members.
         */
        locked: Boolean(value("locked")),
      };

      setDisMemberLoading(true);

      try {
        let saved;

        if (selectedDisMemberId) {
          saved = await apiRequest(
            `/members/${selectedDisMemberId}`,
            {
              method: "PUT",
              body: JSON.stringify(payload),
            }
          );

          setStatus("Member details updated successfully in PostgreSQL.");
        } else {
          saved = await apiRequest("/members", {
            method: "POST",
            body: JSON.stringify({
              ...payload,
              locked: false,
            }),
          });

          setSelectedDisMemberId(saved?.id ?? null);
          setValues((previous) => ({
            ...previous,
            ...payload,
            locked: false,
          }));
          setStatus("Member details saved successfully in PostgreSQL.");
        }

        if (saved?.id) {
          setSelectedDisMemberId(saved.id);
        }

        await loadGenDetailMembers();
      } catch (error) {
        console.error("DIS Gen. Detail save error:", error);
        setStatus(`Unable to save member: ${error.message}`);
      } finally {
        setDisMemberLoading(false);
      }
    };

