  // =========================================================
  // OTHERS -> MARK DISSOLVED GPS
  // PostgreSQL-backed dissolved vazhvathram records.
  // =========================================================

  const loadMarkDissolvedFromDatabase = async () => {
    try {
      setMarkDissolvedLoading(true);

      const data = await apiRequest("/mark-dissolved-groups");
      const records = Array.isArray(data) ? data : [];

      setMarkDissolvedRows(
        records.map((record) => ({
          id: record.id,
          groupName: String(record.groupName || ""),
          markedDissolved: Boolean(record.markedDissolved),
          reason: String(record.reason || ""),
        }))
      );
    } catch (error) {
      console.error("Could not load Mark Dissolved Groups data:", error);
      alert(
        `Unable to load Mark Dissolved Groups data from database.\n${error.message}`
      );
    } finally {
      setMarkDissolvedLoading(false);
    }
  };

  const updateMarkDissolvedRow = (index, field, value) => {
    setMarkDissolvedRows((previous) =>
      previous.map((row, rowIndex) =>
        rowIndex === index ? { ...row, [field]: value } : row
      )
    );
  };

  const saveMarkDissolvedGroups = async () => {
    if (!markDissolvedRows.length) {
      alert("No vazhvathram records available to save. Click List first.");
      return;
    }

    try {
      setMarkDissolvedLoading(true);
      const savedRows = [];

      for (const row of markDissolvedRows) {
        const payload = {
          groupName: String(row.groupName || "").trim(),
          markedDissolved: Boolean(row.markedDissolved),
          reason: String(row.reason || "").trim(),
        };

        if (!payload.groupName) continue;

        const saved = row.id
          ? await apiRequest(`/mark-dissolved-groups/${row.id}`, {
              method: "PUT",
              body: JSON.stringify(payload),
            })
          : await apiRequest("/mark-dissolved-groups", {
              method: "POST",
              body: JSON.stringify(payload),
            });

        savedRows.push({
          id: saved.id,
          groupName: String(saved.groupName || ""),
          markedDissolved: Boolean(saved.markedDissolved),
          reason: String(saved.reason || ""),
        });
      }

      setMarkDissolvedRows(savedRows);
      alert("Mark Dissolved Groups details saved successfully to PostgreSQL!");
    } catch (error) {
      console.error("Mark Dissolved Groups save error:", error);
      alert(
        `Unable to save Mark Dissolved Groups details.\n${error.message}`
      );
    } finally {
      setMarkDissolvedLoading(false);
    }
  };

