        setChangeMeetingLoading(true);

        const endpoint = approvedOnly
          ? `/change-meeting-date/approved?changeDate=${encodeURIComponent(
              changeMeetingDate.trim()
            )}`
          : `/change-meeting-date?changeDate=${encodeURIComponent(
              changeMeetingDate.trim()
            )}`;

        const data = await apiRequest(endpoint);
        const records = Array.isArray(data) ? data : [];

        setChangeMeetingRows(
          records.map((record) => ({
            id: record.id,
            groupName: String(record.groupName || ""),
            meetingDate: String(record.meetingDate || ""),
            approved: Boolean(record.approved),
          }))
        );

        if (!records.length) {
          alert(
            approvedOnly
              ? "No approved groups found."
              : "No meeting date records found."
          );
        }
