  // ---------------------------------------------------------

  const selectedVazText =
    normalizeOB03(selectedVazhvathram);

  const selectedVazRecord =
    vazhvathrams.find((record) => {
      const code = normalizeOB03(
        record?.vazhvathramCode ||
        record?.code ||
        record?.id
      );

      const name = normalizeOB03(
        record?.vazhvathramName ||
        record?.name
      );

      return (
        code === selectedVazText ||
        name === selectedVazText
      );
    }) || null;

  const vazCode =
    selectedVazRecord?.vazhvathramCode ||
    selectedVazRecord?.code ||
    selectedVazhvathram ||
    "";

  const vazName =
    selectedVazRecord?.vazhvathramName ||
    selectedVazRecord?.name ||
    "";

  // ---------------------------------------------------------
  // FIND MEMBER FOR EACH RECEIPT
  // ---------------------------------------------------------

  const findMemberOB03 = (receipt) => {
    const receiptMemberCode =
      normalizeOB03(
        receipt?.memberCode
      );

    const receiptMemberName =
      normalizeOB03(
        receipt?.memberName
      );

    return (
      members.find((member) => {
        const memberCode =
          normalizeOB03(
            member?.memberCode ||
            member?.code ||
            member?.memberId ||
            member?.id
          );

        const memberName =
          normalizeOB03(
            member?.memberName ||
            member?.name
          );

        return (
          (receiptMemberCode &&
            memberCode ===
              receiptMemberCode) ||
          (!receiptMemberCode &&
            receiptMemberName &&
            memberName ===
              receiptMemberName)
        );
      }) || null
    );
  };

  // ---------------------------------------------------------
  // CHECK WHETHER MEMBER BELONGS TO SELECTED VAZHVATHRAM
  // ---------------------------------------------------------

  const memberBelongsToVazOB03 =
    (member) => {
      if (!member) {
        return false;
      }

      const memberVazCode =
        normalizeOB03(
          member?.vazhvathramCode ||
          member?.vazhvathram
        );

      const memberVazName =
        normalizeOB03(
          member?.vazhvathramName ||
          member?.vazhvathramName
        );

      const selectedCode =
        normalizeOB03(vazCode);

      const selectedName =
        normalizeOB03(vazName);

      if (
        memberVazCode &&
        selectedCode
      ) {
        return (
          memberVazCode ===
          selectedCode
        );
      }

      if (
        memberVazName &&
        selectedName
      ) {
        return (
          memberVazName ===
          selectedName
        );
      }

      return false;
    };

  // ---------------------------------------------------------
  // READ MEMBER RECEIPTS
  // ---------------------------------------------------------

  const loanRowsOB03 = [];

  const receiptsOB03 =
    Array.isArray(memberReceipts)
